import { db } from "./lib/db";
import { FREEMC_GAME_TYPES, FREEMC_GAME_MODES, recreateGameTypeContainer } from "./lib/free-minecraft-control";
import { getSetting, getSettingInt } from "./lib/settings";
import { withServerSsh, exec, shellQuote } from "./lib/ssh-exec";
import type { SftpServer } from "./lib/sftp";

const SKIP = new Set(["mc-free-cmrztujaw0002hlazl58i3lsi"]); // papi — already fixed and currently awake, don't touch

async function freemcHost(): Promise<SftpServer> {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } }, node: { select: { publicIp: true } } },
  });
  if (!host) throw new Error("not provisioned");
  return host;
}

(async () => {
  const rows = await db.freeMinecraftServer.findMany({
    select: { id: true, containerName: true, subdomain: true, activeGameType: true, activeGameMode: true, userId: true },
  });
  const targets = rows.filter((r) => FREEMC_GAME_TYPES[r.activeGameType]?.kind === "properties" && !SKIP.has(r.containerName));
  console.log(`Targets: ${targets.map((t) => t.subdomain).join(", ")}`);

  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
  const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);
  const host = await freemcHost();

  await withServerSsh(host, async (conn) => {
    for (const row of targets) {
      // Confirm it's currently asleep before touching it — never wake something
      // that might have a real player on it without checking first.
      const check = await exec(conn, `docker ps --filter ${shellQuote(`name=^/${row.containerName}$`)} --format '{{.Names}}'`, 10_000);
      const wasRunning = check.stdout.trim().length > 0;

      const gameTypeDef = FREEMC_GAME_TYPES[row.activeGameType];
      const gameModeDef = FREEMC_GAME_MODES[row.activeGameMode];
      try {
        const outcome = await recreateGameTypeContainer(conn, {
          containerName: row.containerName,
          dataPath: `/opt/freemc/servers/${row.id}`,
          subdomain: row.subdomain,
          domain,
          ramMb,
          ownerId: row.userId,
          gameType: gameTypeDef,
          gameMode: gameModeDef,
          gameTypeKey: row.activeGameType,
        });
        console.log(`${row.subdomain}: ${outcome.ok ? "OK" : "FAILED - " + outcome.error} (wasRunning=${wasRunning})`);
        if (outcome.ok && !wasRunning) {
          const stop = await exec(conn, `docker stop -t 30 ${shellQuote(row.containerName)}`, 40_000);
          console.log(`  -> returned to sleep: code=${stop.code}`);
        }
      } catch (e) {
        console.log(`${row.subdomain}: THREW - ${e}`);
      }
    }
  });
  await db.$disconnect();

