import { PrismaClient } from "@prisma/client";
import { writeFileSync, chmodSync } from "node:fs";
const db = new PrismaClient();
const BID = "cmsw33mv20000hlokqv7gze6u";
async function main(){
  const cols = await db.boardColumn.findMany({ where: { boardId: BID } });
  const col = cols.find(c => c.name.trim().toLowerCase() === "api tokens");
  if(!col){ console.log("no API Tokens column"); return; }
  const cards = await db.card.findMany({ where: { boardId: BID, columnId: col.id }, orderBy:{position:"asc"} });
  // preserve to a 0600 file (no console echo of secret content)
  const dump = cards.map(c => "### "+c.title+"\n"+(c.description||"")).join("\n\n---\n\n");
  const path = "/opt/nxeon/.kodely-secrets.local";
  writeFileSync(path, "# Preserved from Kodely board 'API Tokens' column on removal.\n# TREAT AS COMPROMISED — ROTATE THESE. chmod 600.\n\n"+dump+"\n");
  chmodSync(path, 0o600);
  // delete the exposed cards
  const ids = cards.map(c=>c.id);
  await db.card.deleteMany({ where: { id: { in: ids } } });
  console.log("preserved "+cards.length+" card(s) to "+path+" (chmod 600) and deleted them from the board.");
  const total = await db.card.count({ where: { boardId: BID } });
  console.log("board now "+total+" cards.");
}
main().catch(e=>{console.error(e.message);process.exit(1);}).finally(()=>db.$disconnect());

