import { PrismaClient } from "/opt/nxeon/node_modules/@prisma/client/index.js";
import { readFileSync } from "node:fs";
import { createDecipheriv, scryptSync } from "node:crypto";
import Anthropic from "/opt/nxeon/node_modules/@anthropic-ai/sdk/index.mjs";

function readEnvVar(path, name) {
  const content = readFileSync(path, "utf8");
  const line = content.split("\n").find((l) => l.startsWith(`${name}=`));
  let v = line.slice(name.length + 1).trim();
  if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1);
  return v;
}
function deriveKey(secret) { return scryptSync(secret, "nxeon-byok", 32); }
function decryptSecret(enc, secret) {
  if (!enc) return null;
  const [ivB64, tagB64, dataB64] = enc.split(":");
  const decipher = createDecipheriv("aes-256-gcm", deriveKey(secret), Buffer.from(ivB64, "base64"));
  decipher.setAuthTag(Buffer.from(tagB64, "base64"));
  const dec = Buffer.concat([decipher.update(Buffer.from(dataB64, "base64")), decipher.final()]);
  return dec.toString("utf8");
}

const dbUrl = readEnvVar("/opt/nxeon/.env", "DATABASE_URL");
const authSecret = readEnvVar("/opt/nxeon/.env", "AUTH_SECRET");
const db = new PrismaClient({ datasources: { db: { url: dbUrl } } });

const row = await db.setting.findUnique({ where: { key: "kb_bot_api_key" } });
const key = decryptSecret(row?.value ?? null, authSecret);
console.log("resolved PROD key prefix:", key?.slice(0, 12), "len:", key?.length);

const client = new Anthropic({ apiKey: key });
try {
  const res = await client.messages.create({
    model: "claude-haiku-4-5",
    max_tokens: 16,
    messages: [{ role: "user", content: "say ok" }],
  });
  console.log("PROD KEY WORKS:", JSON.stringify(res.content));
} catch (e) {
  console.log("error status:", e.status, "message:", e.message);
}
process.exit(0);

