const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1536, height: 1010 } });
  await page.goto('http://localhost:4917/dev-preview-sgmap', { waitUntil: 'networkidle' });
  const info = await page.evaluate(() => {
    const clip = document.querySelector('clipPath');
    const paths = clip ? Array.from(clip.children).map(p => p.getAttribute('d').slice(0,30)) : [];
    const rects = Array.from(document.querySelectorAll('rect')).filter(r => r.getAttribute('clip-path'));
    return {
      clipChildCount: clip ? clip.children.length : -1,
      paths,
      rectClipAttrs: rects.map(r => ({ clip: r.getAttribute('clip-path'), fill: r.getAttribute('fill') })),
      clipId: clip ? clip.id : null,
    };
  });
  console.log(JSON.stringify(info, null, 2));
  await browser.close();
})();
